AND GROUP_CODE IN
#{groupCode}
AND GROUP_CODE = #{groupCode}
AND COMMON_CODE = #{commonCode}
AND DATA_STATUS = #{dataStatus}
AND DATA_STATUS != 'DELETED'
ORDER BY SORT_ORDER

SELECT GROUP_CODE , COMMON_CODE , COMMON_CODE_NAME , COMMON_CODE_DESC AS COMMON_CODE_DESCRIPTION , DATA_STATUS , SORT_ORDER , CREATED_BY , CREATED_AT , UPDATED_BY , UPDATED_AT FROM TB_COMMON_CODE WHERE TRUE
AND GROUP_CODE = #{groupCode}
AND COMMON_CODE = #{commonCode}
AND DATA_STATUS = #{dataStatus}
AND DATA_STATUS != 'DELETED'

mapper.insert:
INSERT INTO TB_COMMON_CODE (
    GROUP_CODE
  , COMMON_CODE
  , COMMON_CODE_NAME
  , COMMON_CODE_DESC
  , DATA_STATUS
  , SORT_ORDER
  , CREATED_BY
  , UPDATED_BY
) VALUES (
    #{groupCode}
  , #{commonCode}
  , #{commonCodeName}
  , #{commonCodeDescription}
  , #{dataStatus}
  , #{sortOrder}
  , #{author}
  , #{author}
)

mapper.update:
UPDATE TB_COMMON_CODE
   SET COMMON_CODE_NAME = #{commonCodeName}
     , COMMON_CODE_DESC = #{commonCodeDescription}
     , DATA_STATUS      = #{dataStatus}
     , UPDATED_BY       = #{author}
     , UPDATED_AT       = NOW()
 WHERE GROUP_CODE       = #{targetGroupCode}
   AND COMMON_CODE      = #{targetCommonCode}
   AND DATA_STATUS     != 'DELETED'

UPDATE TB_COMMON_CODE
   SET DATA_STATUS = 'DELETED'
     , UPDATED_BY  = #{author}
     , UPDATED_AT  = NOW()
 WHERE GROUP_CODE  = #{targetGroupCode}
   AND COMMON_CODE = #{targetCommonCode}
